@Configuration
public class PayAutoConfig {

    @Bean
    @ConditionalOnProperty(name = "pay.channel", havingValue = "alipay")
    public PayService alipayService() { return new AlipayService(); }

    @Bean
    @ConditionalOnProperty(name = "pay.channel", havingValue = "wechat", matchIfMissing = true)
    public PayService wechatService() { return new WechatPayService(); }
}
